148	export async function mcCreateMailbox(opts: {
149	  localPart: string;
150	  domain: string;
151	  name: string;
152	  password: string;
153	  quotaMB: number;
154	}): Promise<unknown> {
155	  return mcRequest("POST", "/add/mailbox", {
156	    local_part: opts.localPart,
157	    domain: opts.domain,
158	    name: opts.name,
159	    password: opts.password,
160	    password2: opts.password,
161	    quota: opts.quotaMB,
162	    active: "1",
163	  });
164	}
