174	/**
175	 * Set a new password on an existing mailbox (customer-initiated reset). Mailcow
176	 * requires both `password` and `password2`; `force_pw_update:"0"` means the user
177	 * is not forced to change it on next webmail login (we just gave them this one).
178	 */
179	export async function mcSetMailboxPassword(address: string, password: string): Promise<unknown> {
180	  return mcRequest("POST", "/edit/mailbox", {
181	    items: [address],
182	    attr: { password, password2: password, force_pw_update: "0" },
183	  });
184	}
