199	// ---------- Aliases ----------
200	
201	/** A mail alias as returned by Mailcow, narrowed to the fields the UI needs. */
202	export type MailcowAlias = {
203	  id: number;
204	  address: string; // the alias address (what mail is sent to)
205	  goto: string; // destination(s), comma-separated
206	  active: boolean;
207	  domain?: string;
208	};
209	
210	/** Coerce Mailcow's mixed number/string `active` flag to a boolean. */
211	function toActive(v: unknown): boolean {
212	  return v === 1 || v === "1" || v === true;
213	}
214	
215	/**
216	 * List all aliases configured on a domain (`GET /get/alias/all/<domain>`).
217	 * Mailcow returns an array of alias objects; a domain with no aliases yields an
218	 * empty array (or `{}`), which we normalise to `[]`.
219	 */
220	export async function mcListAliases(domain: string): Promise<MailcowAlias[]> {
221	  const res = await mcRequest("GET", `/get/alias/all/${encodeURIComponent(domain)}`);
222	  const rows = Array.isArray(res) ? res : [];
223	  const out: MailcowAlias[] = [];
224	  for (const r of rows) {
225	    if (!r || typeof r !== "object") continue;
226	    const o = r as Record<string, unknown>;
227	    const id = Number(o.id);
228	    const address = typeof o.address === "string" ? o.address : "";
229	    if (!Number.isFinite(id) || !address) continue;
230	    out.push({
231	      id,
232	      address,
233	      goto: typeof o.goto === "string" ? o.goto : "",
234	      active: toActive(o.active),
235	      domain: typeof o.domain === "string" ? o.domain : undefined,
236	    });
237	  }
238	  return out;
239	}
240	
241	/**
242	 * Create an alias (`POST /add/alias`). `goto` is the destination address (or a
243	 * comma-separated list) mail to `address` should be delivered to. Throws a
244	 * MailcowError on any logical failure (e.g. the alias already exists).
245	 */
246	export async function mcAddAlias(address: string, goto: string): Promise<unknown> {
247	  return mcRequest("POST", "/add/alias", {
248	    address,
249	    goto,
250	    active: "1",
251	  });
252	}
253	
254	/** Delete an alias by its Mailcow id (`POST /delete/alias` with `[id]`). */
255	export async function mcDeleteAlias(id: number): Promise<unknown> {
256	  return mcRequest("POST", "/delete/alias", [id]);
257	}
258	
259	// ---------- DKIM ----------
260	
261	/**
262	 * Fetch the DKIM public-key TXT value for a domain from Mailcow
263	 * (`GET /api/v1/get/dkim/<domain>`). Mailcow returns an object carrying the
264	 * ready-to-publish TXT in `dkim_txt` (selector `dkim`). Returns the TXT string,
265	 * or null when the domain has no DKIM key yet or the shape is unexpected.
266	 *
267	 * Throws MailcowError only when the integration is unreachable/errors — callers
268	 * that must stay tolerant wrap this in try/catch.
269	 */
270	export async function mcGetDkim(domain: string): Promise<string | null> {
271	  const res = await mcRequest("GET", `/get/dkim/${encodeURIComponent(domain)}`);
272	  if (!res || typeof res !== "object") return null;
273	  // Mailcow returns {} for a domain with no key configured.
274	  const txt = (res as { dkim_txt?: unknown }).dkim_txt;
275	  if (typeof txt === "string" && txt.trim()) return txt.trim();
276	  return null;
277	}
278	
279	// ---------- Analytics ----------
280	
281	export type MailStats = {
282	  configured: true;
283	  domains: number;
284	  mailboxes: number;
285	  postfix: {
286	    sampled: number;
287	    sent: number;
288	    deferred: number;
289	    bounced: number;
290	    rejected: number;
291	    other: number;
292	  };
293	  rspamd: {
294	    sampled: number;
295	    actions: Record<string, number>;
296	    spam: number; // reject + add header + rewrite subject
297	    clean: number; // no action + greylist / soft reject
298	  };
299	};
300	
301	function asArray(v: unknown): unknown[] {
302	  if (Array.isArray(v)) return v;
303	  if (v && typeof v === "object" && Array.isArray((v as { rows?: unknown[] }).rows)) {
304	    return (v as { rows: unknown[] }).rows;
305	  }
306	  return [];
307	}
308	
309	/**
310	 * Pull recent postfix + rspamd logs and domain/mailbox counts for the admin
311	 * deliverability view. Throws (MailcowError) if not configured or unreachable —
312	 * the admin page catches that and shows a graceful fallback.
313	 */
314	export async function mcStats(sample = 400): Promise<MailStats> {
315	  config(); // throws early with a clear message if not configured
316	
317	  const [domainsRaw, mailboxesRaw, postfixRaw, rspamdRaw] = await Promise.all([
318	    mcRequest("GET", "/get/domain/all").catch(() => []),
319	    mcRequest("GET", "/get/mailbox/all").catch(() => []),
320	    mcRequest("GET", `/get/logs/postfix/${sample}`).catch(() => []),
321	    mcRequest("GET", `/get/logs/rspamd-history/${sample}`).catch(() => []),
322	  ]);
323	
324	  const postfixLogs = asArray(postfixRaw);
325	  const postfix = { sampled: postfixLogs.length, sent: 0, deferred: 0, bounced: 0, rejected: 0, other: 0 };
326	  for (const entry of postfixLogs) {
327	    const msg = String(
328	      (entry as { message?: unknown })?.message ??
329	        (entry && typeof entry === "object" ? JSON.stringify(entry) : entry) ??
330	        "",
331	    ).toLowerCase();
332	    if (msg.includes("status=sent")) postfix.sent++;
333	    else if (msg.includes("status=deferred")) postfix.deferred++;
334	    else if (msg.includes("status=bounced")) postfix.bounced++;
335	    else if (msg.includes("reject:") || msg.includes("status=reject")) postfix.rejected++;
336	    else postfix.other++;
337	  }
338	
339	  const rspamdLogs = asArray(rspamdRaw);
340	  const actions: Record<string, number> = {};
341	  let spam = 0;
342	  let clean = 0;
343	  for (const entry of rspamdLogs) {
344	    const action = String((entry as { action?: unknown })?.action ?? "unknown").toLowerCase();
345	    actions[action] = (actions[action] ?? 0) + 1;
346	    if (action === "reject" || action === "add header" || action === "rewrite subject") spam++;
347	    else clean++;
348	  }
349	
350	  return {
351	    configured: true,
352	    domains: asArray(domainsRaw).length,
353	    mailboxes: asArray(mailboxesRaw).length,
354	    postfix,
355	    rspamd: { sampled: rspamdLogs.length, actions, spam, clean },
356	  };
357	}
