1	"use server";
2	
3	// Server actions for the native webmail "Mailbox settings" panel
4	// (components/customer/mail/MailSettings.tsx, opened from the FolderRail).
5	//
6	// Every action authenticates the caller and resolves ONLY a mailbox they own via
7	// `resolveMailbox` (which also performs the ownership check used everywhere else
8	// in the mail client). Writes are rate-limited and return a friendly
9	// `{ ok, error }`. Alias operations additionally verify the target domain is one
10	// the caller actually owns (an EmailSubscription) before touching Mailcow.
11	
12	import { db } from "@/lib/db";
13	import { checkRateLimit } from "@/lib/rate-limit";
14	import { resolveMailbox } from "@/lib/mail/imap";
15	import {
16	  mailcowConfigured,
17	  mcListAliases,
18	  mcAddAlias,
19	  mcDeleteAlias,
20	  type MailcowAlias,
21	} from "@/lib/mailcow";
22	import { resetMailboxPassword } from "@/lib/actions-email-hosting";
23	import { safeHtml } from "@/lib/mail/render";
24	import { signatureHtmlToText, SIGNATURE_HTML_MAX } from "@/lib/mail/signature";
25	
26	export type Result = { ok: boolean; error?: string };
27	
28	const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
29	
30	/** Serialisable mailbox settings the panel reads/writes. */
31	export type MailboxSettings = {
32	  address: string;
33	  domain: string;
34	  displayName: string;
35	  // Identity
36	  replyTo: string;
37	  organization: string;
38	  // Signature
39	  signature: string; // derived / legacy plain-text
40	  signatureHtml: string; // sanitized rich HTML (source of truth)
41	  signatureEnabled: boolean;
42	  signatureOnReply: boolean;
43	  signaturePlacement: "above" | "below";
44	  // Auto-reply
45	  autoReplyEnabled: boolean;
46	  autoReplySubject: string;
47	  autoReplyBody: string;
48	  autoReplyStart: string; // "YYYY-MM-DD" or ""
49	  autoReplyEnd: string; // "YYYY-MM-DD" or ""
50	  // Forwarding (stored)
51	  forwardingAddress: string;
52	  forwardKeepCopy: boolean;
53	  // Storage
54	  quotaMB: number | null;
55	};
56	
57	function domainOf(address: string): string {
58	  const at = address.lastIndexOf("@");
59	  return at >= 0 ? address.slice(at + 1).toLowerCase() : "";
60	}
61	
62	/** Format a stored Date as a `YYYY-MM-DD` string (or "" when null). */
63	function toDateInput(d: Date | null | undefined): string {
64	  if (!d) return "";
65	  try {
66	    return d.toISOString().slice(0, 10);
67	  } catch {
68	    return "";
69	  }
70	}
71	
72	/** Parse a `YYYY-MM-DD` string into a UTC Date, or null when blank/invalid. */
73	function fromDateInput(s: string | null | undefined): Date | null {
74	  const v = (s ?? "").trim();
75	  if (!v) return null;
76	  const d = new Date(`${v}T00:00:00.000Z`);
77	  return Number.isNaN(d.getTime()) ? null : d;
78	}
79	
80	/** Rate-limit gate returning a friendly `{ ok:false }` instead of throwing. */
81	function gate(key: string, max: number, windowMs: number): Result | null {
82	  const r = checkRateLimit(key, { max, windowMs });
83	  if (!r.ok) return { ok: false, error: `Too many requests — wait ${r.retryAfterSec}s and try again.` };
84	  return null;
85	}
86	
87	/** The domains the signed-in user owns (from their email subscriptions). */
88	async function ownedDomains(userId: string): Promise<Set<string>> {
89	  const subs = await db.emailSubscription.findMany({
90	    where: { userId },
91	    select: { domainName: true },
92	  });
93	  return new Set(subs.map((s) => s.domainName.trim().toLowerCase()).filter(Boolean));
94	}
95	
96	// ---------------------------------------------------------------------------
97	// Identity, signature, auto-reply (stored on the Mailbox row)
98	// ---------------------------------------------------------------------------
99	
100	/** Load the current settings for a mailbox the caller owns. */
101	export async function getMailboxSettings(mailboxAddress?: string): Promise<MailboxSettings> {
102	  const { mailboxId, address } = await resolveMailbox(mailboxAddress);
103	  const row = await db.mailbox.findUnique({ where: { id: mailboxId } });
104	  const placement = row?.signaturePlacement === "above" ? "above" : "below";
105	  return {
106	    address,
107	    domain: domainOf(address),
108	    displayName: row?.displayName ?? "",
109	    replyTo: row?.replyTo ?? "",
110	    organization: row?.organization ?? "",
111	    signature: row?.signature ?? "",
112	    signatureHtml: row?.signatureHtml ?? "",
113	    signatureEnabled: row?.signatureEnabled ?? true,
114	    signatureOnReply: row?.signatureOnReply ?? true,
115	    signaturePlacement: placement,
116	    autoReplyEnabled: row?.autoReplyEnabled ?? false,
117	    autoReplySubject: row?.autoReplySubject ?? "",
118	    autoReplyBody: row?.autoReplyBody ?? "",
119	    autoReplyStart: toDateInput(row?.autoReplyStart),
120	    autoReplyEnd: toDateInput(row?.autoReplyEnd),
121	    forwardingAddress: row?.forwardingAddress ?? "",
122	    forwardKeepCopy: row?.forwardKeepCopy ?? true,
123	    quotaMB: row?.quotaMB ?? null,
124	  };
125	}
126	
127	/**
128	 * Save identity + signature onto the mailbox row. Only the fields actually
129	 * present in `input` are written, so the Identity and Signature sub-forms can
130	 * each save independently without clobbering the other's data.
131	 *
132	 * Signature HTML is sanitised server-side with `safeHtml` (defence in depth —
133	 * the client sanitises too) and a plain-text version is derived into the legacy
134	 * `signature` column so the text/plain MIME part always has a fallback.
135	 */
136	export async function saveMailboxSettings(
137	  input: {
138	    displayName?: string;
139	    replyTo?: string;
140	    organization?: string;
141	    signatureHtml?: string;
142	    signatureEnabled?: boolean;
143	    signatureOnReply?: boolean;
144	    signaturePlacement?: string;
145	  },
146	  mailboxAddress?: string,
147	): Promise<Result> {
148	  const { user, mailboxId } = await resolveMailbox(mailboxAddress);
149	  const limited = gate(`mail:settings:${user.id}`, 30, 60_000);
150	  if (limited) return limited;
151	
152	  const data: {
153	    displayName?: string | null;
154	    replyTo?: string | null;
155	    organization?: string | null;
156	    signatureHtml?: string | null;
157	    signature?: string | null;
158	    signatureEnabled?: boolean;
159	    signatureOnReply?: boolean;
160	    signaturePlacement?: string;
161	  } = {};
162	
163	  if (input.displayName !== undefined) {
164	    const displayName = input.displayName.trim();
165	    if (displayName.length > 120) return { ok: false, error: "Display name is too long (max 120 characters)." };
166	    data.displayName = displayName || null;
167	  }
168	
169	  if (input.replyTo !== undefined) {
170	    const replyTo = input.replyTo.trim();
171	    if (replyTo && !EMAIL_RE.test(replyTo)) return { ok: false, error: "Reply-to must be a valid email address." };
172	    data.replyTo = replyTo || null;
173	  }
174	
175	  if (input.organization !== undefined) {
176	    const organization = input.organization.trim();
177	    if (organization.length > 200) return { ok: false, error: "Organization is too long (max 200 characters)." };
178	    data.organization = organization || null;
179	  }
180	
181	  if (input.signatureHtml !== undefined) {
182	    const clean = safeHtml(input.signatureHtml);
183	    if (clean.length > SIGNATURE_HTML_MAX) {
184	      return { ok: false, error: "Signature is too long. Please shorten it." };
185	    }
186	    data.signatureHtml = clean || null;
187	    const plain = signatureHtmlToText(clean);
188	    data.signature = plain ? plain : null;
189	  }
190	
191	  if (input.signatureEnabled !== undefined) data.signatureEnabled = Boolean(input.signatureEnabled);
192	  if (input.signatureOnReply !== undefined) data.signatureOnReply = Boolean(input.signatureOnReply);
193	  if (input.signaturePlacement !== undefined) {
194	    data.signaturePlacement = input.signaturePlacement === "above" ? "above" : "below";
195	  }
196	
197	  if (Object.keys(data).length > 0) {
198	    await db.mailbox.update({ where: { id: mailboxId }, data });
199	  }
200	  return { ok: true };
201	}
202	
203	/**
204	 * Store a "forward a copy" rule on the mailbox row.
205	 *
206	 * NOTE: this is STORE-ONLY and honestly labelled as such in the UI. Mailcow has
207	 * no safe, mailbox-scoped forwarding primitive we can drive from the customer
208	 * panel without risking the account's real mail routing (an alias whose address
209	 * equals an existing mailbox is rejected by Mailcow, and editing SOGo sieve
210	 * filters is out of API scope), so we persist the preference and surface a
211	 * clear "stored, not yet auto-forwarding" note rather than pretend it forwards.
212	 */
213	export async function saveForwarding(
214	  input: { enabled: boolean; address?: string; keepCopy?: boolean },
215	  mailboxAddress?: string,
216	): Promise<Result> {
217	  const { user, mailboxId, address } = await resolveMailbox(mailboxAddress);
218	  const limited = gate(`mail:settings:${user.id}`, 30, 60_000);
219	  if (limited) return limited;
220	
221	  const enabled = Boolean(input.enabled);
222	  const target = (input.address ?? "").trim().toLowerCase();
223	  const keepCopy = input.keepCopy !== false;
224	
225	  if (enabled) {
226	    if (!target) return { ok: false, error: "Enter an address to forward to." };
227	    if (!EMAIL_RE.test(target)) return { ok: false, error: "That doesn't look like a valid email address." };
228	    if (target === address.toLowerCase()) return { ok: false, error: "Forwarding to this mailbox itself does nothing." };
229	  }
230	
231	  await db.mailbox.update({
232	    where: { id: mailboxId },
233	    data: {
234	      forwardingAddress: enabled && target ? target : null,
235	      forwardKeepCopy: keepCopy,
236	    },
237	  });
238	  return { ok: true };
239	}
240	
241	/**
242	 * Save the auto-reply / vacation responder onto the mailbox row.
243	 *
244	 * NOTE: this is STORE-ONLY. Mailcow's REST API exposes no reliable
245	 * vacation/auto-responder endpoint (auto-replies live in SOGo user preferences,
246	 * not the admin API), so we persist the settings and the UI labels them as
247	 * "saved; server-side delivery is rolling out". We do NOT pretend the mail
248	 * server sends them.
249	 */
250	export async function saveAutoReply(
251	  input: { enabled: boolean; subject?: string; body?: string; start?: string | null; end?: string | null },
252	  mailboxAddress?: string,
253	): Promise<Result> {
254	  const { user, mailboxId } = await resolveMailbox(mailboxAddress);
255	  const limited = gate(`mail:settings:${user.id}`, 30, 60_000);
256	  if (limited) return limited;
257	
258	  const enabled = Boolean(input.enabled);
259	  const subject = (input.subject ?? "").trim();
260	  const body = (input.body ?? "").trim();
261	  if (subject.length > 200) return { ok: false, error: "Subject is too long (max 200 characters)." };
262	  if (body.length > 5000) return { ok: false, error: "Message is too long (max 5000 characters)." };
263	  if (enabled && !body) return { ok: false, error: "Add an auto-reply message before turning it on." };
264	
265	  const start = fromDateInput(input.start);
266	  const end = fromDateInput(input.end);
267	  if (start && end && start.getTime() > end.getTime()) {
268	    return { ok: false, error: "The start date must be on or before the end date." };
269	  }
270	
271	  await db.mailbox.update({
272	    where: { id: mailboxId },
273	    data: {
274	      autoReplyEnabled: enabled,
275	      autoReplySubject: subject || null,
276	      autoReplyBody: body || null,
277	      autoReplyStart: start,
278	      autoReplyEnd: end,
279	    },
280	  });
281	  return { ok: true };
282	}
