313	/**
314	 * Add an alias on a domain the caller owns. `alias` may be a full address or a
315	 * bare local part (the mailbox's own domain is assumed). `goto` defaults to the
316	 * mailbox itself.
317	 */
318	export async function addAlias(alias: string, goto?: string, mailboxAddress?: string): Promise<Result> {
319	  const { user, address } = await resolveMailbox(mailboxAddress);
320	  const limited = gate(`mail:alias:${user.id}`, 20, 60_000);
321	  if (limited) return limited;
322	  if (!mailcowConfigured()) return { ok: false, error: "Mail server is not configured yet." };
323	
324	  let aliasAddr = (alias ?? "").trim().toLowerCase();
325	  if (!aliasAddr) return { ok: false, error: "Enter an alias address." };
326	  // Accept a bare local part — assume the mailbox's own domain.
327	  if (!aliasAddr.includes("@")) aliasAddr = `${aliasAddr}@${domainOf(address)}`;
328	  if (!EMAIL_RE.test(aliasAddr)) return { ok: false, error: "That doesn't look like a valid email address." };
329	
330	  const owned = await ownedDomains(user.id);
331	  if (!owned.has(domainOf(aliasAddr))) {
332	    return { ok: false, error: "You can only add aliases on a domain you own." };
333	  }
334	
335	  const dest = (goto ?? "").trim() || address;
336	  if (!EMAIL_RE.test(dest)) return { ok: false, error: "The destination address is not valid." };
337	  if (dest.toLowerCase() === aliasAddr) return { ok: false, error: "An alias can't point to itself." };
338	
339	  try {
340	    await mcAddAlias(aliasAddr, dest);
341	    return { ok: true };
342	  } catch (e) {
343	    return { ok: false, error: friendly(e) };
344	  }
345	}
