220	/**
221	 * Walk a BODYSTRUCTURE tree and return the IMAP part id of the best text part
222	 * to preview: prefers text/plain, then text/html, then the first leaf. Returns
223	 * "1" for a simple single-part message (whose structure carries no part id).
224	 */
225	export function findPreviewPart(structure: MessageStructureObject | undefined): { part: string; isHtml: boolean } {
226	  if (!structure) return { part: "1", isHtml: false };
227	  const leaves: MessageStructureObject[] = [];
228	  const walk = (node: MessageStructureObject) => {
229	    if (node.childNodes && node.childNodes.length) {
230	      node.childNodes.forEach(walk);
231	    } else {
232	      leaves.push(node);
233	    }
234	  };
235	  walk(structure);
236	
237	  const isBody = (n: MessageStructureObject) => (n.disposition || "").toLowerCase() !== "attachment";
238	  const plain = leaves.find((n) => (n.type || "").toLowerCase() === "text/plain" && isBody(n));
239	  if (plain) return { part: plain.part || "1", isHtml: false };
240	  const html = leaves.find((n) => (n.type || "").toLowerCase() === "text/html" && isBody(n));
241	  if (html) return { part: html.part || "1", isHtml: true };
242	  return { part: leaves[0]?.part || "1", isHtml: (leaves[0]?.type || "").toLowerCase() === "text/html" };
243	}
244	
245	/** True if a BODYSTRUCTURE tree contains at least one attachment-like part. */
246	export function structureHasAttachments(structure: MessageStructureObject | undefined): boolean {
247	  if (!structure) return false;
248	  let found = false;
249	  const walk = (node: MessageStructureObject) => {
250	    const type = (node.type || "").toLowerCase();
251	    const disp = (node.disposition || "").toLowerCase();
252	    if (node.childNodes && node.childNodes.length) {
253	      node.childNodes.forEach(walk);
254	      return;
255	    }
256	    if (disp === "attachment") found = true;
257	    else if (!type.startsWith("text/") && !type.startsWith("multipart/")) found = true;
258	  };
259	  walk(structure);
260	  return found;
261	}
