474	/** Set or clear the \Seen or \Flagged flag on a message. */
475	export async function setFlag(
476	  folder: string,
477	  uid: number,
478	  flag: "seen" | "flagged",
479	  value: boolean,
480	  mailboxAddress?: string,
481	): Promise<void> {
482	  const { user, cred } = await resolveMailbox(mailboxAddress);
483	  enforceRateLimit(`mail:flag:${user.id}`, { max: 240, windowMs: 60 * 1000 });
484	  const imapFlag = flag === "seen" ? "\\Seen" : "\\Flagged";
485	  await withMailbox(cred, folder, async (client) => {
486	    if (value) await client.messageFlagsAdd(String(uid), [imapFlag], { uid: true });
487	    else await client.messageFlagsRemove(String(uid), [imapFlag], { uid: true });
488	  });
489	}
