297	function SignatureSection({
298	  mailboxAddress,
299	  initial,
300	  onSaved,
301	}: {
302	  mailboxAddress?: string;
303	  initial: MailboxSettings;
304	  onSaved: (v: Partial<MailboxSettings>) => void;
305	}) {
306	  const editorRef = useRef<HTMLDivElement | null>(null);
