311	
312	  const seedHtml =
313	    (initial.signatureHtml && safeHtml(initial.signatureHtml)) ||
314	    (initial.signature ? plainToHtml(initial.signature) : "");
315	
316	  const [html, setHtml] = useState(seedHtml); // mirrors editor content, for preview + save
317	  const [enabled, setEnabled] = useState(initial.signatureEnabled);
318	  const [onReply, setOnReply] = useState(initial.signatureOnReply);
319	  const [placement, setPlacement] = useState<SignaturePlacement>(initial.signaturePlacement);
320	  const [saving, setSaving] = useState(false);
321	  const [msg, setMsg] = useState<string | null>(null);
322	  const [err, setErr] = useState<string | null>(null);
323	
324	  // --- Image resize: click-to-select + a size control (presets + slider/number). ---
325	  // The active image is only tracked in state + tagged with an editor-only class for
326	  // the selection ring; that class is stripped before the HTML is ever read for save.
327	  const [activeImg, setActiveImg] = useState<HTMLImageElement | null>(null);
328	  const [imgWidth, setImgWidth] = useState(320);
329	  const [imgFull, setImgFull] = useState(false);
330	
331	  // Seed the contentEditable once (React never re-writes it, so the caret is safe).
332	  useEffect(() => {
333	    if (editorRef.current) editorRef.current.innerHTML = seedHtml;
334	    // eslint-disable-next-line react-hooks/exhaustive-deps
335	  }, []);
336	
337	  // Read the editor HTML with editor-only artifacts (the image selection ring class)
338	  // stripped, so the stored signature never carries a selection outline or empty class.
339	  const getCleanHtml = useCallback(() => {
340	    const el = editorRef.current;
341	    if (!el) return "";
342	    const clone = el.cloneNode(true) as HTMLElement;
343	    clone.querySelectorAll("img").forEach((im) => {
344	      im.classList.remove("nx-img-active");
345	      if (!im.getAttribute("class")) im.removeAttribute("class");
346	    });
347	    return clone.innerHTML;
348	  }, []);
349	
350	  const sync = useCallback(() => setHtml(getCleanHtml()), [getCleanHtml]);
351	
352	  // Highlight an image as the active one (adds the editor-only ring class) and
353	  // initialise the size control from its current inline width.
354	  const selectImg = useCallback((img: HTMLImageElement) => {
355	    const el = editorRef.current;
356	    if (el) el.querySelectorAll("img.nx-img-active").forEach((i) => i.classList.remove("nx-img-active"));
357	    img.classList.add("nx-img-active");
358	    const sw = img.style.width.trim();
359	    const full = sw === "100%";
360	    let w = 0;
361	    if (sw.endsWith("px")) w = parseInt(sw, 10);
362	    if (!w) w = Math.round(img.getBoundingClientRect().width) || img.naturalWidth || 320;
363	    setActiveImg(img);
364	    setImgFull(full);
365	    setImgWidth(clampImgWidth(w));
366	  }, []);
367	
368	  const deselectImg = useCallback(() => {
369	    const el = editorRef.current;
370	    if (el)
371	      el.querySelectorAll("img.nx-img-active").forEach((i) => {
372	        i.classList.remove("nx-img-active");
373	        if (!i.getAttribute("class")) i.removeAttribute("class");
374	      });
375	    setActiveImg(null);
376	  }, []);
377	
378	  // Apply a fixed pixel width, keeping max-width:100% + height:auto so it never
379	  // overflows the email or distorts. Updates live as the slider moves.
380	  const applyImgWidth = useCallback(
381	    (px: number) => {
382	      const img = activeImg;
383	      if (!img) return;
384	      const w = clampImgWidth(px);
385	      img.style.width = `${w}px`;
386	      img.style.maxWidth = "100%";
387	      img.style.height = "auto";
388	      setImgFull(false);
