391	    },
392	    [activeImg, sync],
393	  );
394	
395	  const applyImgFull = useCallback(() => {
396	    const img = activeImg;
397	    if (!img) return;
398	    img.style.width = "100%";
399	    img.style.maxWidth = "100%";
400	    img.style.height = "auto";
401	    setImgFull(true);
402	    sync();
403	  }, [activeImg, sync]);
404	
405	  const resetImgSize = useCallback(() => {
406	    const img = activeImg;
407	    if (!img) return;
408	    img.style.width = "";
409	    img.style.maxWidth = "100%";
410	    img.style.height = "auto";
411	    setImgFull(false);
412	    setImgWidth(clampImgWidth(Math.round(img.getBoundingClientRect().width) || img.naturalWidth || 320));
413	    sync();
414	  }, [activeImg, sync]);
415	
416	  // Click inside the editor: select a clicked image, else drop any selection.
417	  const onEditorClick = useCallback(
418	    (e: React.MouseEvent) => {
419	      const t = e.target as HTMLElement | null;
420	      if (t && t.tagName === "IMG") selectImg(t as HTMLImageElement);
421	      else deselectImg();
422	    },
423	    [selectImg, deselectImg],
424	  );
425	
426	  const saveSel = useCallback(() => {
427	    const sel = window.getSelection();
428	    if (sel && sel.rangeCount > 0) {
429	      const r = sel.getRangeAt(0);
430	      if (editorRef.current && editorRef.current.contains(r.commonAncestorContainer)) {
431	        savedRange.current = r.cloneRange();
432	      }
433	    }
434	  }, []);
435	
436	  const restoreSel = useCallback(() => {
437	    const el = editorRef.current;
438	    if (!el) return;
439	    el.focus();
440	    const sel = window.getSelection();
441	    if (savedRange.current && sel) {
442	      try {
443	        sel.removeAllRanges();
444	        sel.addRange(savedRange.current);
445	      } catch {
446	        /* range detached — leave caret where it is */
447	      }
448	    }
449	  }, []);
450	
451	  // Run an execCommand, degrading gracefully if the browser doesn't support it.
452	  const exec = useCallback(
453	    (cmd: string, value?: string) => {
454	      try {
455	        restoreSel();
