457	      } catch {
458	        /* unsupported command — ignore rather than crash the editor */
459	      }
460	      saveSel();
461	      sync();
462	    },
463	    [restoreSel, saveSel, sync],
464	  );
465	
466	  const insertHtml = useCallback(
467	    (fragment: string) => {
468	      const el = editorRef.current;
469	      if (!el) return;
470	      restoreSel();
471	      let ok = false;
472	      try {
473	        ok = document.execCommand("insertHTML", false, fragment);
474	      } catch {
475	        ok = false;
476	      }
477	      if (!ok) el.innerHTML = el.innerHTML + fragment; // fallback: append
478	      saveSel();
479	      sync();
480	    },
481	    [restoreSel, saveSel, sync],
482	  );
483	
484	  function promptLink() {
485	    const url = window.prompt("Link URL", "https://");
486	    if (!url) return;
487	    exec("createLink", url.trim());
488	  }
489	
490	  function promptImage() {
491	    const url = window.prompt("Image URL (https://…)", "https://");
492	    if (!url) return;
493	    setImgErr(null);
494	    insertHtml(`<img src="${escAttr(url.trim())}" style="max-width:100%" />`);
495	  }
496	
497	  // Primary path: open the OS file picker to upload an image from the computer.
498	  function pickImage() {
499	    setImgErr(null);
500	    saveSel(); // remember the caret before the file dialog steals focus
501	    fileInputRef.current?.click();
502	  }
503	
504	  async function onImageFile(e: React.ChangeEvent<HTMLInputElement>) {
505	    const file = e.target.files?.[0];
506	    e.target.value = ""; // allow re-picking the same file later
507	    if (!file) return;
508	
509	    setImgErr(null);
510	    setUploading(true);
511	    try {
512	      const body = new FormData();
513	      body.append("file", file);
514	      const res = await fetch("/api/mail/signature-image", { method: "POST", body });
515	      const data = (await res.json().catch(() => ({}))) as { url?: string; error?: string };
516	      if (!res.ok || !data.url) {
517	        setImgErr(data.error || "Couldn't upload that image.");
518	        return;
519	      }
520	      // Insert at the saved caret so the dialog's focus loss doesn't drop it.
521	      insertHtml(`<img src="${escAttr(data.url)}" style="max-width:100%" />`);
522	    } catch {
523	      setImgErr("Couldn't upload that image. Please try again.");
524	    } finally {
525	      setUploading(false);
526	    }
527	  }
528	
529	  function clearFormatting() {
530	    exec("removeFormat");
531	    exec("unlink");
532	  }
533	
534	  async function save() {
535	    setSaving(true);
536	    setMsg(null);
537	    setErr(null);
538	    try {
539	      const clean = safeHtml(getCleanHtml());
540	      const res = await saveMailboxSettings(
541	        { signatureHtml: clean, signatureEnabled: enabled, signatureOnReply: onReply, signaturePlacement: placement },
542	        mailboxAddress,
543	      );
544	      if (!res.ok) {
545	        setErr(res.error || "Couldn't save.");
546	      } else {
547	        setMsg("Saved.");
548	        setHtml(clean);
549	        onSaved({
550	          signatureHtml: clean,
551	          signature: signatureHtmlToText(clean),
552	          signatureEnabled: enabled,
553	          signatureOnReply: onReply,
554	          signaturePlacement: placement,
555	        });
556	      }
557	    } catch (e) {
558	      setErr(e instanceof Error ? e.message : "Couldn't save.");
559	    } finally {
560	      setSaving(false);
561	    }
562	  }
563	
564	  const templates = signatureTemplates({
565	    name: initial.displayName,
566	    org: initial.organization,
567	    email: initial.address,
568	  });
569	  const previewHtml = safeHtml(html);
570	
571	  return (
