1037	function fmtBytes(n: number): string {
1038	  if (!Number.isFinite(n) || n <= 0) return "0 MB";
1039	  const units = ["B", "KB", "MB", "GB", "TB"];
1040	  let v = n;
1041	  let i = 0;
1042	  while (v >= 1024 && i < units.length - 1) {
1043	    v /= 1024;
1044	    i++;
1045	  }
1046	  return `${v >= 10 || i === 0 ? Math.round(v) : v.toFixed(1)} ${units[i]}`;
1047	}
1048	
1049	function StorageSection({
1050	  initial,
1051	  usedBytes,
1052	  quotaBytes,
1053	}: {
1054	  initial: MailboxSettings;
1055	  usedBytes?: number;
1056	  quotaBytes?: number;
1057	}) {
1058	  const quota =
1059	    quotaBytes && quotaBytes > 0
1060	      ? quotaBytes
1061	      : initial.quotaMB
1062	        ? initial.quotaMB * 1024 * 1024
1063	        : 0;
1064	  const used = usedBytes && usedBytes > 0 ? usedBytes : 0;
1065	  const haveUsage = usedBytes !== undefined;
1066	  const pct = quota > 0 ? Math.min(100, Math.round((used / quota) * 100)) : 0;
1067	  const nearFull = pct >= 90;
1068	
1069	  return (
1070	    <div className="space-y-5">
1071	      <SectionHead title="Storage" sub="How much of this mailbox's quota is in use." />
1072	
1073	      <div className="rounded-2xl border border-white/[0.08] bg-white/[0.02] p-5">
1074	        <div className="flex items-baseline justify-between">
1075	          <span className="text-2xl font-semibold text-white">{fmtBytes(used)}</span>
1076	          <span className="text-sm text-slate-400">of {quota > 0 ? fmtBytes(quota) : "—"}</span>
1077	        </div>
1078	
1079	        <div className="mt-3 h-2.5 w-full overflow-hidden rounded-full bg-white/10">
1080	          <div
1081	            className={`h-full rounded-full ${nearFull ? "bg-gradient-to-r from-amber-400 to-red-400" : "bg-gradient-to-r from-accent-blue to-brand-500"}`}
1082	            style={{ width: `${quota > 0 ? pct : 0}%` }}
1083	          />
1084	        </div>
1085	
1086	        <p className="mt-2 text-xs text-slate-500">
1087	          {quota > 0 ? `${pct}% used` : "Quota not set"}
1088	          {!haveUsage && " — live usage is unavailable right now; showing your plan quota."}
1089	          {nearFull && haveUsage && " — you're running low. Clear out large messages or upgrade your plan."}
1090	        </p>
1091	      </div>
1092	    </div>
1093	  );
1094	}
