1140	function AliasesSection({ mailboxAddress, domain }: { mailboxAddress?: string; domain: string }) {
1141	  const [aliases, setAliases] = useState<AliasRow[] | null>(null);
1142	  const [loadErr, setLoadErr] = useState<string | null>(null);
1143	  const [newAlias, setNewAlias] = useState("");
1144	  const [busy, setBusy] = useState(false);
1145	  const [err, setErr] = useState<string | null>(null);
1146	
1147	  const load = useCallback(async () => {
1148	    setLoadErr(null);
1149	    try {
1150	      const res = await listAliases(mailboxAddress);
1151	      if (!res.ok) {
1152	        setLoadErr(res.error || "Couldn't load aliases.");
1153	        setAliases([]);
1154	      } else {
1155	        setAliases(res.aliases);
1156	      }
1157	    } catch (e) {
1158	      setLoadErr(e instanceof Error ? e.message : "Couldn't load aliases.");
1159	      setAliases([]);
1160	    }
1161	  }, [mailboxAddress]);
1162	
1163	  useEffect(() => {
1164	    void load();
1165	  }, [load]);
1166	
1167	  async function add() {
1168	    const val = newAlias.trim();
1169	    if (!val) return;
1170	    setBusy(true);
1171	    setErr(null);
