/** Delete a mailbox. */
export async function mcDeleteMailbox(address: string): Promise<unknown> {
  return mcRequest("POST", "/delete/mailbox", [address]);
}

// ---------- Mailbox discovery (read-only) ----------

/** A mailbox as it actually exists on Mailcow, narrowed to what we can adopt. */
export type MailcowMailbox = {
  address: string; // Mailcow's `username` — the full email address
  domain: string;
  name: string;
  active: boolean;
  quotaBytes: number;
  quotaUsedBytes: number;
};

/**
 * List the mailboxes that really exist on a domain (`GET /get/mailbox/all/<domain>`).
 *
 * WHY this exists: `resolveMailbox` used to read only `db.mailbox`, so a mailbox
 * that lives on Mailcow without a local row was completely invisible in the
 * portal — the "it's not detecting the mailbox I already have on this account"
 * report. This is the read half of the reconciliation; the adoption half
 * (lib/mail/imap.ts `discoverMailboxes`) gates on domain verification.
 *
 * A domain Mailcow doesn't know returns `{}`, which we normalise to `[]`.
 */
export async function mcListMailboxes(domain: string): Promise<MailcowMailbox[]> {
  const res = await mcRequest("GET", `/get/mailbox/all/${encodeURIComponent(domain)}`);
  const rows = Array.isArray(res) ? res : [];
  const want = domain.trim().toLowerCase();
  const out: MailcowMailbox[] = [];
  for (const r of rows) {
    if (!r || typeof r !== "object") continue;
    const o = r as Record<string, unknown>;
    const address = typeof o.username === "string" ? o.username.trim().toLowerCase() : "";
    if (!address.includes("@")) continue;
    const mboxDomain =
      typeof o.domain === "string" ? o.domain.trim().toLowerCase() : address.slice(address.lastIndexOf("@") + 1);
    // Never return a row for a different domain than the one asked for — the
    // caller uses the domain to decide ownership, so it must not be spoofable
    // by a surprising API response shape.
    if (mboxDomain !== want) continue;
    out.push({
      address,
      domain: mboxDomain,
      name: typeof o.name === "string" ? o.name : "",
      active: toActive(o.active),
      quotaBytes: Number(o.quota) > 0 ? Number(o.quota) : 0,
      quotaUsedBytes: Number(o.quota_used) > 0 ? Number(o.quota_used) : 0,
    });
  }
  return out;
}

// ---------- Sieve filters (auto-reply + forwarding) ----------

/**
 * A per-mailbox sieve filter as stored in Mailcow's `sieve_filters` table.
 *
 * Mailcow chains scripts as: global_sieve_before -> user `prefilter` ->
 * the user's own personal script -> user `postfilter` -> global_sieve_after.
 * Only ONE filter per (username, filter_type) can be active at a time —
 * Mailcow deactivates the others whenever a filter is added/edited as active.
 * That is why lib/mail/sieve.ts compiles auto-reply AND forwarding into a
 * single managed script instead of one filter each.
 */
export type MailcowFilter = {
  id: number;
  username: string;
  scriptDesc: string;
  scriptData: string;
  filterType: string; // "prefilter" | "postfilter"
  active: boolean;
};

export type MailcowFilterType = "prefilter" | "postfilter";

function toFilterRows(res: unknown): MailcowFilter[] {
  const rows = Array.isArray(res) ? res : [];
  const out: MailcowFilter[] = [];
  for (const r of rows) {
    if (!r || typeof r !== "object") continue;
    const o = r as Record<string, unknown>;
    const id = Number(o.id);
    if (!Number.isFinite(id)) continue;
    out.push({
      id,
      username: typeof o.username === "string" ? o.username : "",
      scriptDesc: typeof o.script_desc === "string" ? o.script_desc : "",
      scriptData: typeof o.script_data === "string" ? o.script_data : "",
      filterType: typeof o.filter_type === "string" ? o.filter_type : "",
      active: toActive(o.active),
    });
  }
  return out;
}

/**
 * List the sieve filters belonging to ONE mailbox
 * (`GET /get/filters/<address>`). Mailcow returns `{}` when there are none.
 *
 * Always pass a full address: `/get/filters/all` walks every domain on the
 * server, which would leak other tenants' scripts into our result.
 */
export async function mcListFilters(address: string): Promise<MailcowFilter[]> {
  const res = await mcRequest("GET", `/get/filters/${encodeURIComponent(address)}`);
  // Defence in depth: Mailcow scopes by username server-side, but we re-filter
  // so a wrong/greedy response can never hand one customer another's script.
  const want = address.trim().toLowerCase();
  return toFilterRows(res).filter((f) => f.username.trim().toLowerCase() === want);
}

/** Create a sieve filter on a mailbox (`POST /add/filter`). */
export async function mcAddFilter(opts: {
  address: string;
  scriptDesc: string;
  scriptData: string;
  filterType: MailcowFilterType;
  active?: boolean;
}): Promise<unknown> {
  return mcRequest("POST", "/add/filter", {
    username: opts.address,
    script_desc: opts.scriptDesc,
    script_data: opts.scriptData,
    filter_type: opts.filterType,
    active: opts.active === false ? "0" : "1",
  });
}

/**
 * Replace the body of an existing filter (`POST /edit/filter`).
 *
 * Mailcow keeps the current value for any field it receives EMPTY, so
 * `scriptData` must never be blank here — clearing a rule is a delete, not an
 * edit with an empty script.
 */
export async function mcEditFilter(
  id: number,
  attr: { scriptDesc: string; scriptData: string; filterType: MailcowFilterType; active?: boolean },
): Promise<unknown> {
  if (!attr.scriptData.trim()) {
    throw new MailcowError("Refusing to edit a sieve filter with an empty script — delete it instead.");
  }
  return mcRequest("POST", "/edit/filter", {
    items: [id],
    attr: {
      script_desc: attr.scriptDesc,
      script_data: attr.scriptData,
      filter_type: attr.filterType,
      active: attr.active === false ? "0" : "1",
    },
  });
}

/** Delete a sieve filter by its Mailcow id (`POST /delete/filter`). */
export async function mcDeleteFilter(id: number): Promise<unknown> {
  return mcRequest("POST", "/delete/filter", [id]);
}

// ---------- DKIM ----------

