export async function mcGetDkim(domain: string): Promise<string | null> {
  return (await mcGetDkimDetails(domain))?.txt ?? null;
}

/** The signing key Mailcow will actually use, plus the selector it publishes under. */
export type MailcowDkim = { selector: string; txt: string; bits: number | null };

/**
 * Fetch the LIVE DKIM key + selector for a domain.
 *
 * The deliverability self-check must compare published DNS against this, never
 * against `EmailSubscription.dkimRecord`: that column is a cache written once at
 * DNS-setup time, so if the key is ever rotated (or the domain re-created on
 * Mailcow, which regenerates it) the cache silently describes a key that no
 * longer signs anything — and the check would tell a customer their DNS is
 * correct while every message they send fails DKIM.
 */
export async function mcGetDkimDetails(domain: string): Promise<MailcowDkim | null> {
  const res = await mcRequest("GET", `/get/dkim/${encodeURIComponent(domain)}`);
  if (!res || typeof res !== "object") return null;
  // Mailcow returns {} for a domain with no key configured.
  const o = res as Record<string, unknown>;
  const txt = typeof o.dkim_txt === "string" ? o.dkim_txt.trim() : "";
  if (!txt) return null;
  const selector = typeof o.dkim_selector === "string" && o.dkim_selector.trim() ? o.dkim_selector.trim() : "dkim";
  const bits = Number(o.length);
  return { selector, txt, bits: Number.isFinite(bits) && bits > 0 ? bits : null };
}

