// Sieve compiler for the customer-facing mailbox rules (auto-reply + forwarding).
//
// Plain server-side module (NO "use server"): pure string building, no I/O. The
// caller (lib/actions-mailbox-settings.ts) pushes the result to Mailcow.
//
// WHY this file exists: auto-reply and forwarding were STORE-ONLY. The panel
// said "saved", nothing on the mail server changed, and a customer who switched
// on an out-of-office before a holiday got no auto-replies and no forwarded mail
// at all. Mailcow's REST API does expose per-mailbox sieve filters, and the
// self-hosted Dovecot has the extensions we need — verified read-only against
// the live server and against mailcow's own config:
//
//   sieve_extensions = +notify +imapflags +vacation-seconds +editheader
//   sieve_vacation_send_from_recipient = yes   (auto-reply is From: the mailbox)
//   sieve_redirect_envelope_from = recipient
//
// `vacation`, `copy`, `date` and `relational` are all in Pigeonhole's default
// extension set AND in mailcow's PHP sieve validator
// (data/web/inc/lib/sieve/extensions/*.xml), which rejects the whole API call if
// a `require` names something it doesn't know. Only those four are used here.
//
// Everything is compiled into ONE script because Mailcow keeps at most one
// ACTIVE filter per (mailbox, filter_type) — adding a second active filter
// silently deactivates the first, which would make enabling forwarding turn the
// customer's auto-reply back off.

/** The rule state we compile from — the persisted Mailbox columns, verbatim. */
export type MailboxRuleState = {
  address: string;
  autoReplyEnabled: boolean;
  autoReplySubject: string | null;
  autoReplyBody: string | null;
  autoReplyStart: Date | null;
  autoReplyEnd: Date | null;
  forwardingAddress: string | null;
  forwardKeepCopy: boolean;
};

/**
 * `script_desc` we tag our filter with. This is the ONLY thing that identifies a
 * script as ours, so the sync path never edits or deletes a filter a customer
 * (or an operator) created by hand in Mailcow's own UI.
 */
export const NXEON_SIEVE_DESC = "Nxeon mailbox settings (managed — do not edit)";

/**
 * Mailcow's `prefilter` maps to Dovecot `sieve_before`, so these rules run ahead
 * of the mailbox's own personal script. Forwarding and out-of-office must not be
 * defeated by a later "file everything into a folder" rule.
 */
export const NXEON_SIEVE_TYPE = "prefilter" as const;

// Markers so the live script can be read back and reported honestly in the UI
// without re-parsing sieve. `getMailRuleStatus` looks for exactly these.
export const MARK_AUTOREPLY = "# nxeon:autoreply";
export const MARK_FORWARD = "# nxeon:forward";

/**
 * Quote a value as a sieve quoted-string (RFC 5228 §2.4.2).
 *
 * Backslash first, then the quote character — reversing the order would
 * double-escape. Control characters are dropped rather than escaped: sieve has
 * no escape form for them, and a stray NUL or ESC in the body would make
 * Mailcow's validator reject the entire save. CRLF is legal inside a quoted
 * string, so multi-line auto-reply bodies survive intact.
 */
function sq(value: string): string {
  const cleaned = value
    // eslint-disable-next-line no-control-regex
    .replace(/[�-  -]/g, "")
    .replace(/\r\n|\r|\n/g, "\n");
  const escaped = cleaned.replace(/\\/g, "\\\\").replace(/"/g, '\\"').replace(/\n/g, "\r\n");
  return `"${escaped}"`;
}

/** Format a Date as the `YYYY-MM-DD` string sieve's `date`/`"date"` part yields. */
function isoDay(d: Date): string {
  return d.toISOString().slice(0, 10);
}

/**
 * Compile the mailbox's rules into a sieve script, or return "" when the
 * customer has nothing enabled (the caller then DELETES the managed filter, so
 * turning a rule off really turns it off on the server).
 */
export function buildMailboxSieve(state: MailboxRuleState): string {
  const requires = new Set<string>();
  const body: string[] = [];

  const autoReplyBody = (state.autoReplyBody ?? "").trim();
  const autoReplyOn = state.autoReplyEnabled && autoReplyBody.length > 0;
  const forwardTo = (state.forwardingAddress ?? "").trim().toLowerCase();
  const forwardOn = forwardTo.length > 0;

  if (autoReplyOn) {
    requires.add("vacation");

    // `:days 1` is Pigeonhole's dedupe window: one auto-reply per sender per day,
    // so a mailing list or a retrying sender can't be answered in a loop.
    const args = [":days 1", `:addresses [${sq(state.address)}]`];
    const subject = (state.autoReplySubject ?? "").trim();
    // An empty `:subject` is invalid; omitting it lets Pigeonhole use
    // "Auto: <original subject>", which is better than a blank Subject header.
    if (subject) args.push(`:subject ${sq(subject)}`);
    const vacation = `vacation ${args.join(" ")} ${sq(autoReplyBody)};`;

    // The date window is enforced ON THE SERVER, not by us flipping a flag on a
    // schedule — nothing in this codebase runs a job to re-push sieve at
    // midnight, so a client-side window would have kept replying forever.
    const guards: string[] = [];
    if (state.autoReplyStart) guards.push(`currentdate :value "ge" "date" ${sq(isoDay(state.autoReplyStart))}`);
    if (state.autoReplyEnd) guards.push(`currentdate :value "le" "date" ${sq(isoDay(state.autoReplyEnd))}`);

    body.push(MARK_AUTOREPLY);
    if (guards.length === 0) {
      body.push(vacation);
    } else {
      requires.add("date");
      requires.add("relational");
      const test = guards.length === 1 ? guards[0] : `allof (${guards.join(",\n          ")})`;
      body.push(`if ${test}`, "{", `  ${vacation}`, "}");
    }
  }

  if (forwardOn) {
    body.push("", MARK_FORWARD);
    if (state.forwardKeepCopy) {
      // `redirect :copy` leaves the implicit keep intact, so the message is both
      // forwarded and delivered here.
      requires.add("copy");
      body.push(`redirect :copy ${sq(forwardTo)};`);
    } else {
      // A bare `redirect` cancels the implicit keep; `stop` ends the script chain
      // so no later script in the sequence can re-introduce a local delivery.
      body.push(`redirect ${sq(forwardTo)};`, "stop;");
    }
  }

  if (body.length === 0) return "";

  const header = [
    "# Generated by Nxeon from your mailbox settings. Changes here are overwritten.",
    `# Mailbox: ${state.address.replace(/[\r\n]/g, "")}`,
  ];
  const requireLine =
    requires.size > 0 ? `require [${[...requires].sort().map((r) => sq(r)).join(", ")}];` : "";

  return [...header, requireLine, "", ...body]
    .filter((line, i, all) => !(line === "" && all[i - 1] === "")) // no double blanks
    .join("\r\n")
    .concat("\r\n");
}

/** True when the live script on the server is one we generated. */
export function isNxeonSieve(scriptDesc: string): boolean {
  return scriptDesc.trim() === NXEON_SIEVE_DESC;
}

