/** The sender identity the customer configured, applied to every outgoing message. */
export type MailboxIdentity = {
  displayName: string | null;
  replyTo: string | null;
  organization: string | null;
};

/** The subscription context a mailbox hangs off, for verification-aware guards. */
export type ResolvedSubscription = {
  id: string;
  domainName: string;
  external: boolean;
  verified: boolean;
  status: string;
};

/** A user mailbox row plus the decrypted credential, resolved + ownership-checked. */
export type ResolvedMailbox = {
  user: User;
  mailboxId: string;
  address: string;
  quotaMB: number | null;
  cred: MailboxCredentials;
  identity: MailboxIdentity;
  subscription: ResolvedSubscription;
};

/**
 * Adopt mailboxes that exist on Mailcow but have no local `Mailbox` row.
 *
 * WHY: `resolveMailbox` read ONLY `db.mailbox`, so a mailbox created directly on
 * the mail server — or one whose row was lost — was invisible in the portal even
 * though real mail was landing in it ("its not detecting the mailbox that i
 * already have on this account"). This reconciles the two.
 *
 * OWNERSHIP GUARD — the whole point of this function is that it MUST NOT become
 * a way to acquire someone else's mailbox:
 *   1. Only domains on a non-cancelled subscription owned by THIS user are read.
 *   2. Only subscriptions with `verified === true` are eligible. Owning a
 *      subscription ROW is not proof of owning the DOMAIN — an unverified
 *      external subscription is just a claim, and adopting on a claim would
 *      re-open the cross-tenant takeover fixed on 2026-07-25 by a side door.
 *   3. `Mailbox.address` is globally `@unique`, and we skip any address that
 *      already has a row, so a mailbox another tenant legitimately holds is
 *      never re-pointed at this user.
 *   4. `passwordEnc` is left NULL. We never learn the existing password, so the
 *      customer is told to reset it — adoption grants visibility, not access.
 *
 * Never throws: a Mailcow outage must not turn the mail page into an error.
 * Returns the number of rows created.
 */
export async function discoverMailboxes(userId: string): Promise<number> {
  if (!mailcowConfigured()) return 0;

  // Guard against hammering Mailcow: the mail page calls this on every load for
  // an account with no mailbox, which is exactly the account that reaches here.
  const gate = checkRateLimit(`mail:discover:${userId}`, { max: 1, windowMs: 30_000 });
  if (!gate.ok) return 0;

  const subs = await db.emailSubscription.findMany({
    where: { userId, status: { not: "CANCELLED" }, verified: true },
    select: { id: true, domainName: true },
  });
  if (subs.length === 0) return 0;

  let created = 0;
  for (const sub of subs) {
    const domain = sub.domainName.trim().toLowerCase();
    if (!domain) continue;

    let remote: Awaited<ReturnType<typeof mcListMailboxes>>;
    try {
      remote = await mcListMailboxes(domain);
    } catch (e) {
      console.warn(`[mailcow] discovery for ${domain} failed:`, e);
      continue;
    }
    if (remote.length === 0) continue;

    const existing = await db.mailbox.findMany({
      where: { address: { in: remote.map((m) => m.address) } },
      select: { address: true },
    });
    const known = new Set(existing.map((m) => m.address.toLowerCase()));

    for (const m of remote) {
      if (known.has(m.address)) continue;
      try {
        await db.mailbox.create({
          data: {
            subscriptionId: sub.id,
            address: m.address,
            quotaMB: m.quotaBytes > 0 ? Math.round(m.quotaBytes / (1024 * 1024)) : null,
            status: m.active ? "ACTIVE" : "SUSPENDED",
            displayName: m.name && m.name !== m.address ? m.name : null,
          },
        });
        created++;
      } catch {
        // Unique-violation race (two tabs discovering at once) — the row exists
        // now either way, which is the outcome we wanted.
      }
    }
  }

  if (created > 0) {
    await db.auditLog
      .create({ data: { userId, action: "mailbox.discover", detail: `adopted ${created} from mail server` } })
      .catch(() => {});
  }
  return created;
}

/**
 * Why the caller can't open webmail, so the UI can say what is actually wrong
 * instead of one catch-all "No mailbox connected".
 */
export type MailAccessState =
  | { kind: "ok"; address: string }
  | { kind: "no-subscription" }
  | { kind: "unverified-domain"; domains: string[] }
  | { kind: "no-mailbox"; domains: string[] }
  | { kind: "no-password"; address: string }
  | { kind: "server-unreachable"; address: string };

/**
 * Diagnose mail access for a user. Runs Mailcow discovery first so a mailbox
 * that only exists on the server is found before we declare there is none.
 */
export async function mailAccessState(userId: string): Promise<MailAccessState> {
  await discoverMailboxes(userId).catch(() => 0);

  const subs = await db.emailSubscription.findMany({
    where: { userId, status: { not: "CANCELLED" } },
    select: { domainName: true, verified: true, external: true },
  });
  if (subs.length === 0) return { kind: "no-subscription" };

  const boxes = await db.mailbox.findMany({
    where: { subscription: { userId } },
    orderBy: { createdAt: "asc" },
    select: { address: true, passwordEnc: true },
  });

  if (boxes.length === 0) {
    const unverified = subs.filter((s) => !s.verified).map((s) => s.domainName);
    const verified = subs.filter((s) => s.verified).map((s) => s.domainName);
    // An unverified domain is the more actionable problem: no mailbox can even
    // be created on it yet, so lead with that.
    if (verified.length === 0) return { kind: "unverified-domain", domains: unverified };
    return { kind: "no-mailbox", domains: verified };
  }

  const withPassword = boxes.find((b) => decryptSecret(b.passwordEnc));
  if (!withPassword) return { kind: "no-password", address: boxes[0].address };

  // A mailbox and a credential exist, so the page's failure was the mail server
  // itself (IMAP down, auth rejected, TLS problem) — not missing setup.
  return { kind: "server-unreachable", address: withPassword.address };
}

/**
 * Resolve the mailbox a request may act on. Requires an authenticated user,
 * loads only mailboxes belonging to that user's email subscriptions, and (when
 * `mailboxAddress` is given) verifies it is one of them. Decrypts the stored
 * credential; throws a friendly error if the password was never captured.
 *
 * NEVER returns a mailbox the caller does not own.
 */
export async function resolveMailbox(mailboxAddress?: string): Promise<ResolvedMailbox> {
  const user = await requireUser();
  const load = () =>
    db.mailbox.findMany({
      where: { subscription: { userId: user.id } },
      include: { subscription: true },
      orderBy: { createdAt: "asc" },
    });

  let boxes = await load();
  const wanted = mailboxAddress?.trim().toLowerCase();

  // A miss here used to be terminal, which is how a mailbox that exists on the
  // mail server but has no local row became "you do not have a mailbox yet".
  // Reconcile against Mailcow (verified domains only) before giving that answer.
  if (boxes.length === 0 || (wanted && !boxes.some((b) => b.address.toLowerCase() === wanted))) {
    if (await discoverMailboxes(user.id).catch(() => 0)) boxes = await load();
  }

  if (boxes.length === 0) {
    throw new Error("You do not have a mailbox yet. Add an email plan to use webmail.");
  }

  let box = boxes[0];
  if (wanted) {
    const match = boxes.find((b) => b.address.toLowerCase() === wanted);
    if (!match) throw new Error("You do not have access to that mailbox.");
    box = match;
  }

  const password = decryptSecret(box.passwordEnc);
  if (!password) {
    throw new Error("Please reset your mailbox password first to enable webmail access.");
  }

  return {
    user,
    mailboxId: box.id,
    address: box.address,
    quotaMB: box.quotaMB ?? null,
    cred: { address: box.address, password },
    identity: {
      displayName: box.displayName,
      replyTo: box.replyTo,
      organization: box.organization,
    },
    subscription: {
      id: box.subscription.id,
      domainName: box.subscription.domainName,
      external: box.subscription.external,
      verified: box.subscription.verified,
      status: box.subscription.status,
    },
  };
}

