// ---------------------------------------------------------------------------
// Server-side rules: auto-reply + forwarding, as real Mailcow sieve filters
// ---------------------------------------------------------------------------
//
// These two were STORE-ONLY: the panel wrote the DB, showed a green "Saved",
// and NOTHING on the mail server changed. A customer switching on an
// out-of-office before a holiday got no auto-replies and no forwarded mail. The
// old comments claimed the API had no primitive for this; it does —
// `POST /add|edit|delete/filter` drives Dovecot sieve per mailbox (see
// lib/mail/sieve.ts for the capability audit).
//
// The whole rule set is compiled into ONE managed script and pushed BEFORE the
// DB is written, so the stored preference and the live server never disagree.
// If Mailcow rejects the push the DB is left untouched and the customer sees the
// failure — the opposite of the "Saved" lie this replaces.

/** Live state of the managed sieve script, read back from the mail server. */
export type MailRuleStatus = {
  /** Rules can be enforced at all (Mailcow configured + reachable + domain verified). */
  supported: boolean;
  /** The server is currently running our auto-reply / forwarding rule. */
  autoReplyLive: boolean;
  forwardingLive: boolean;
  /** Why enforcement is unavailable, when it is. */
  error?: string;
};

/** Load the rule columns for a mailbox we have already ownership-checked. */
async function ruleState(mailboxId: string, address: string): Promise<MailboxRuleState> {
  const row = await db.mailbox.findUnique({
    where: { id: mailboxId },
    select: {
      autoReplyEnabled: true,
      autoReplySubject: true,
      autoReplyBody: true,
      autoReplyStart: true,
      autoReplyEnd: true,
      forwardingAddress: true,
      forwardKeepCopy: true,
    },
  });
  return {
    address,
    autoReplyEnabled: row?.autoReplyEnabled ?? false,
    autoReplySubject: row?.autoReplySubject ?? null,
    autoReplyBody: row?.autoReplyBody ?? null,
    autoReplyStart: row?.autoReplyStart ?? null,
    autoReplyEnd: row?.autoReplyEnd ?? null,
    forwardingAddress: row?.forwardingAddress ?? null,
    forwardKeepCopy: row?.forwardKeepCopy ?? true,
  };
}

/**
 * Push `state` to Mailcow as the mailbox's single managed sieve filter.
 *
 * Idempotent: reuses our existing filter when there is one, prunes duplicates
 * left by an interrupted save, and DELETES the filter when nothing is enabled so
 * switching a rule off really switches it off on the server.
 *
 * Only ever touches a filter whose `script_desc` is ours — a filter an operator
 * created by hand in Mailcow's own UI is left completely alone.
 *
 * Throws on failure; callers translate that into a user-visible error and skip
 * the DB write.
 */
async function pushMailboxSieve(state: MailboxRuleState): Promise<void> {
  const script = buildMailboxSieve(state);
  const existing = (await mcListFilters(state.address)).filter((f) => isNxeonSieve(f.scriptDesc));

  if (!script) {
    for (const f of existing) await mcDeleteFilter(f.id);
    return;
  }

  const [keep, ...duplicates] = existing;
  for (const f of duplicates) await mcDeleteFilter(f.id);

  if (keep) {
    await mcEditFilter(keep.id, {
      scriptDesc: NXEON_SIEVE_DESC,
      scriptData: script,
      filterType: NXEON_SIEVE_TYPE,
      active: true,
    });
  } else {
    await mcAddFilter({
      address: state.address,
      scriptDesc: NXEON_SIEVE_DESC,
      scriptData: script,
      filterType: NXEON_SIEVE_TYPE,
      active: true,
    });
  }
}

/**
 * Guard shared by both rule savers.
 *
 * A sieve `redirect` sends a copy of every inbound message somewhere else, so
 * this is exactly the primitive a cross-tenant takeover would want. Owning the
 * subscription ROW is not proof of owning the DOMAIN (the 2026-07-25 finding),
 * so an unverified external domain is refused outright.
 */
function assertRulesAllowed(sub: {
  external: boolean;
  verified: boolean;
  status: string;
}): { ok: false; error: string } | null {
  if (!mailcowConfigured()) {
    return { ok: false, error: "Mail server is not configured yet — rules can't be applied." };
  }
  if (sub.status === "CANCELLED") {
    return { ok: false, error: "This subscription is cancelled." };
  }
  if (sub.external && !sub.verified) {
    return {
      ok: false,
      error: "Verify this domain first (Business Email → Verify DNS) before setting up mail rules.",
    };
  }
  return null;
}

/**
 * Report what the mail server is ACTUALLY running, so the panel can stop
 * guessing. Derived from the live script's markers, not from the DB — if a rule
 * was never applied (or was removed on the server) this says so.
 */
export async function getMailRuleStatus(mailboxAddress?: string): Promise<MailRuleStatus> {
  const { address, subscription } = await resolveMailbox(mailboxAddress);
  const blocked = assertRulesAllowed(subscription);
  if (blocked) return { supported: false, autoReplyLive: false, forwardingLive: false, error: blocked.error };

  try {
    const mine = (await mcListFilters(address)).find((f) => isNxeonSieve(f.scriptDesc) && f.active);
    return {
      supported: true,
      autoReplyLive: Boolean(mine?.scriptData.includes(MARK_AUTOREPLY)),
      forwardingLive: Boolean(mine?.scriptData.includes(MARK_FORWARD)),
    };
  } catch (e) {
    return {
      supported: false,
      autoReplyLive: false,
      forwardingLive: false,
      error: `Couldn't reach the mail server to read your rules: ${friendly(e)}`,
    };
  }
}

/**
 * Forward inbound mail to another address, enforced by a real sieve `redirect`.
 * "Keep a copy" maps to `redirect :copy` (implicit keep survives); without it a
 * bare `redirect` + `stop` forwards without local delivery.
 */
export async function saveForwarding(
  input: { enabled: boolean; address?: string; keepCopy?: boolean },
  mailboxAddress?: string,
): Promise<Result> {
  const { user, mailboxId, address, subscription } = await resolveMailbox(mailboxAddress);
  const limited = gate(`mail:settings:${user.id}`, 30, 60_000);
  if (limited) return limited;

  const enabled = Boolean(input.enabled);
  const target = (input.address ?? "").trim().toLowerCase();
  const keepCopy = input.keepCopy !== false;

  if (enabled) {
    if (!target) return { ok: false, error: "Enter an address to forward to." };
    if (!EMAIL_RE.test(target)) return { ok: false, error: "That doesn't look like a valid email address." };
    if (target.length > 200) return { ok: false, error: "That address is too long." };
    if (target === address.toLowerCase()) return { ok: false, error: "Forwarding to this mailbox itself does nothing." };
  }

  const blocked = assertRulesAllowed(subscription);
  if (blocked) return blocked;

  const next: MailboxRuleState = {
    ...(await ruleState(mailboxId, address)),
    forwardingAddress: enabled && target ? target : null,
    forwardKeepCopy: keepCopy,
  };

  try {
    await pushMailboxSieve(next);
  } catch (e) {
    // Deliberately do NOT persist: a stored "forwarding on" that the server is
    // not running is the exact defect this replaces.
    return { ok: false, error: `Couldn't apply forwarding on the mail server: ${friendly(e)}` };
  }

  await db.mailbox.update({
    where: { id: mailboxId },
    data: { forwardingAddress: next.forwardingAddress, forwardKeepCopy: next.forwardKeepCopy },
  });

  await db.auditLog
    .create({
      data: {
        userId: user.id,
        action: "mailbox.forwarding",
        detail: `${address} → ${next.forwardingAddress ?? "off"}${next.forwardingAddress && !keepCopy ? " (no local copy)" : ""}`,
      },
    })
    .catch(() => {});

  return { ok: true };
}

/**
 * Out-of-office responder, enforced by a real sieve `vacation`. The date window
 * is compiled into the script as a `currentdate` test so the mail server starts
 * and stops replying on its own — nothing here runs on a schedule, so a window
 * evaluated in this process would simply never stop.
 */
export async function saveAutoReply(
  input: { enabled: boolean; subject?: string; body?: string; start?: string | null; end?: string | null },
  mailboxAddress?: string,
): Promise<Result> {
  const { user, mailboxId, address, subscription } = await resolveMailbox(mailboxAddress);
  const limited = gate(`mail:settings:${user.id}`, 30, 60_000);
  if (limited) return limited;

  const enabled = Boolean(input.enabled);
  const subject = (input.subject ?? "").trim();
  const body = (input.body ?? "").trim();
  if (subject.length > 200) return { ok: false, error: "Subject is too long (max 200 characters)." };
  if (body.length > 5000) return { ok: false, error: "Message is too long (max 5000 characters)." };
  if (enabled && !body) return { ok: false, error: "Add an auto-reply message before turning it on." };

  const start = fromDateInput(input.start);
  const end = fromDateInput(input.end);
  if (start && end && start.getTime() > end.getTime()) {
    return { ok: false, error: "The start date must be on or before the end date." };
  }

  const blocked = assertRulesAllowed(subscription);
  if (blocked) return blocked;

  const next: MailboxRuleState = {
    ...(await ruleState(mailboxId, address)),
    autoReplyEnabled: enabled,
    autoReplySubject: subject || null,
    autoReplyBody: body || null,
    autoReplyStart: start,
    autoReplyEnd: end,
  };

  try {
    await pushMailboxSieve(next);
  } catch (e) {
    return { ok: false, error: `Couldn't apply the auto-reply on the mail server: ${friendly(e)}` };
  }

  await db.mailbox.update({
    where: { id: mailboxId },
    data: {
      autoReplyEnabled: next.autoReplyEnabled,
      autoReplySubject: next.autoReplySubject,
      autoReplyBody: next.autoReplyBody,
      autoReplyStart: next.autoReplyStart,
      autoReplyEnd: next.autoReplyEnd,
    },
  });

  await db.auditLog
    .create({
      data: {
        userId: user.id,
        action: "mailbox.autoreply",
        detail: `${address} → ${enabled ? "on" : "off"}`,
      },
    })
    .catch(() => {});

  return { ok: true };
}

