input.content:
// Per-domain mail deliverability self-check (SPF / DKIM / DMARC / MX).
//
// Plain server-side module (NO "use server") — the ownership-checked server
// action lives in lib/actions-email-hosting.ts.
//
// WHY: customers land in spam with no way to find out why. That is exactly what
// happened to the platform owner: mail was silently failing authentication and
// the only diagnosis available was an external third-party tool. This gives every
// customer a pass/fail per record with the value we ACTUALLY observed next to the
// value we expect, so "my mail goes to spam" becomes a fixable DNS row.
//
// ============================ THE RESOLVER TRAP =============================
// This check MUST NOT use the system resolver. This host has:
//
//     /etc/nsswitch.conf -> hosts: files myhostname dns
//
// and a populated /etc/hosts. During today's incident a reverse lookup returned a
// value straight out of that local text file while appearing to have asked
// Cloudflare and Google — which produced a completely confident, completely wrong
// diagnosis. A customer-facing check built on the system resolver would tell
// people their DNS is broken when it is fine, or the reverse.
//
// So: resolve the zone's NS records through PINNED public resolvers, resolve
// those nameservers to IPs, then query THOSE nameservers directly for every
// record. The answer then comes from the zone's own authority — no /etc/hosts, no
// inherited /etc/resolv.conf, no recursive-cache staleness after the customer
// has just fixed a record.
// ============================================================================

import { Resolver } from "node:dns/promises";

/** Public resolvers used ONLY to find the zone's nameservers. Never the OS list. */
const BOOTSTRAP_RESOLVERS = ["1.1.1.1", "8.8.8.8", "9.9.9.9"];

const DNS_TIMEOUT_MS = 4000;
const DNS_TRIES = 2;

export type CheckStatus = "pass" | "warn" | "fail" | "unknown";

export type DeliverabilityCheck = {
  key: "mx" | "spf" | "dkim" | "dmarc";
  label: string;
  status: CheckStatus;
  /** What the authoritative nameservers actually returned (empty = nothing published). */
  observed: string;
  /** What we need to see there. */
  expected: string;
  /** One line the customer can act on. */
  detail: string;
  /** The DNS name that was queried, so the customer knows which row to edit. */
  host: string;
  type: "MX" | "TXT";
};

export type DeliverabilityReport = {
  domain: string;
  /** The authoritative nameservers we queried — shown so the result is auditable. */
  nameservers: string[];
  checks: DeliverabilityCheck[];
  /** Set when we could not establish authority at all (checks will be `unknown`). */
  error?: string;
  checkedAt: string;
};

function bootstrapResolver(): Resolver {
  const r = new Resolver({ timeout: DNS_TIMEOUT_MS, tries: DNS_TRIES });
  // Explicit setServers is the entire point — a bare `new Resolver()` inherits
  // /etc/resolv.conf, which is the failure mode described at the top of this file.
  r.setServers(BOOTSTRAP_RESOLVERS);
  return r;
}

/** All parent zones of a name, apex last: a.b.example.com -> b.example.com, example.com. */
function parentZones(domain: string): string[] {
  const labels = domain.split(".").filter(Boolean);
  const out: string[] = [];
  for (let i = 0; i < labels.length - 1; i++) out.push(labels.slice(i).join("."));
  return out;
}

/**
 * Find the zone's authoritative nameservers and return a Resolver pinned to them.
 *
 * Walks up from the queried name because a mail domain can be a subdomain whose
 * NS records live on the parent zone; without the walk a perfectly healthy
 * `mail.customer.com` would report "we can't find your nameservers".
 */
async function authoritativeResolver(
  domain: string,
): Promise<{ resolver: Resolver; nameservers: string[] } | { error: string }> {
  const boot = bootstrapResolver();

  let nameservers: string[] = [];
  for (const zone of [domain, ...parentZones(domain)]) {
    try {
      const ns = await boot.resolveNs(zone);
      if (ns.length > 0) {
        nameservers = ns.map((n) => n.replace(/\.$/, "").toLowerCase());
        break;
      }
    } catch {
      // NXDOMAIN / ENODATA at this level — try the parent zone.
    }
  }
  if (nameservers.length === 0) {
    return { error: "No nameservers found for this domain — check it is registered and delegated." };
  }

  const ips: string[] = [];
  for (const ns of nameservers) {
    const [v4, v6] = await Promise.all([
      boot.resolve4(ns).catch(() => [] as string[]),
      boot.resolve6(ns).catch(() => [] as string[]),
    ]);
    ips.push(...v4, ...v6);
  }
  if (ips.length === 0) {
    return { error: `Could not resolve this domain's nameservers (${nameservers.join(", ")}) to an address.` };
  }

  const resolver = new Resolver({ timeout: DNS_TIMEOUT_MS, tries: DNS_TRIES });
  resolver.setServers(ips);
  return { resolver, nameservers };
}

/** A TXT record's chunks are concatenated with NO separator (RFC 7208 §3.3). */
function joinTxt(record: string[]): string {
  return record.join("").trim();
}

async function txtAt(resolver: Resolver, host: string): Promise<string[] | null> {
  try {
    return (await resolver.resolveTxt(host)).map(joinTxt).filter(Boolean);
  } catch {
    // NXDOMAIN / ENODATA from the authority means "not published".
    return null;
  }
}

/** Normalise a DKIM TXT value so cosmetic differences don't read as a mismatch. */
function dkimKey(value: string): string {
  const m = value.match(/(?:^|[;\s])p=([A-Za-z0-9+/=]*)/);
  return m ? m[1] : "";
}

function truncate(v: string, max = 180): string {
  return v.length > max ? `${v.slice(0, max)}…` : v;
}

/**
 * Run the four authentication checks for `domain`.
 *
 * `mailHost` is the MX we expect, `spfInclude` the mechanism that authorises our
 * sending host, and `dkim` MUST be the LIVE key read from Mailcow
 * (`GET /get/dkim/<domain>` → `dkim_txt`), never the cached
 * `EmailSubscription.dkimRecord`: a stale cache would confirm a key that no
 * longer signs anything.
 */
export async function checkDeliverability(opts: {
  domain: string;
  mailHost: string;
  spfInclude: string;
  spfExpected: string;
  dmarcExpected: string;
  dkim: { selector: string; txt: string } | null;
}): Promise<DeliverabilityReport> {
  const domain = opts.domain.trim().toLowerCase().replace(/\.$/, "");
  const checkedAt = new Date().toISOString();
  const dkimSelector = opts.dkim?.selector || "dkim";
  const dkimHost = `${dkimSelector}._domainkey.${domain}`;

  const auth = await authoritativeResolver(domain);
  if ("error" in auth) {
    const unknown = (
      key: DeliverabilityCheck["key"],
      label: string,
      host: string,
      type: DeliverabilityCheck["type"],
      expected: string,
    ): DeliverabilityCheck => ({
      key,
      label,
      status: "unknown",
      observed: "",
      expected,
      detail: "Couldn't reach this domain's nameservers to read the record.",
      host,
      type,
    });
    return {
      domain,
      nameservers: [],
      error: auth.error,
      checkedAt,
      checks: [
        unknown("mx", "MX — mail routing", domain, "MX", `${opts.mailHost} (priority 10)`),
        unknown("spf", "SPF — authorised senders", domain, "TXT", opts.spfExpected),
        unknown("dkim", "DKIM — message signing", dkimHost, "TXT", opts.dkim?.txt ?? "(no key on the mail server yet)"),
        unknown("dmarc", "DMARC — policy", `_dmarc.${domain}`, "TXT", opts.dmarcExpected),
      ],
    };
  }

  const { resolver, nameservers } = auth;

  const [mxRecords, apexTxt, dkimTxt, dmarcTxt] = await Promise.all([
    resolver.resolveMx(domain).catch(() => null),
    txtAt(resolver, domain),
    txtAt(resolver, dkimHost),
    txtAt(resolver, `_dmarc.${domain}`),
  ]);

  const checks: DeliverabilityCheck[] = [];

  // ---- MX ----------------------------------------------------------------
  {
    const rows = (mxRecords ?? []).map((r) => ({
      exchange: r.exchange.replace(/\.$/, "").toLowerCase(),
      priority: r.priority,
    }));
    const observed = rows.length
      ? rows
          .slice()
          .sort((a, b) => a.priority - b.priority)
          .map((r) => `${r.exchange} (${r.priority})`)
          .join(", ")
      : "";
    const ours = rows.some((r) => r.exchange === opts.mailHost);
    checks.push({
      key: "mx",
      label: "MX — mail routing",
      status: ours ? (rows.length > 1 ? "warn" : "pass") : rows.length ? "fail" : "fail",
      observed,
      expected: `${opts.mailHost} (priority 10)`,
      host: domain,
      type: "MX",
      detail: !rows.length
        ? "No MX record published — inbound mail for this domain has nowhere to go."
        : ours
          ? rows.length > 1
            ? "Our mail host is listed, but so are others — mail may be delivered to a different server."
            : "Inbound mail is routed to the Nxeon mail server."
          : `Mail is routed elsewhere. Point the MX at ${opts.mailHost} or inbound mail will never reach these mailboxes.`,
    });
  }

  // ---- SPF ---------------------------------------------------------------
  {
    const spfRecords = (apexTxt ?? []).filter((t) => /^v=spf1\b/i.test(t));
    const observed = spfRecords.join(" | ");
    let status: CheckStatus = "fail";
    let detail: string;
    if (spfRecords.length === 0) {
      detail = "No SPF record published — receivers have nothing authorising us to send for you.";
    } else if (spfRecords.length > 1) {
      status = "fail";
      detail = "More than one SPF record. RFC 7208 makes that a permanent error — merge them into one.";
    } else {
      const spf = spfRecords[0];
      const authorised =
        spf.toLowerCase().includes(`include:${opts.spfInclude}`) ||
        // `mx` authorises whatever the MX points at, which is our mail host when
        // the MX check above passes — a valid, commonly-used alternative.
        /(?:^|\s)mx(?:\s|$)/i.test(spf);
      if (authorised) {
        status = /[~-]all\s*$/.test(spf) ? "pass" : "warn";
        detail =
          status === "pass"
            ? "The Nxeon mail server is authorised to send for this domain."
            : "Authorised, but the record has no `~all`/`-all` terminator, so receivers apply no policy to unauthorised senders.";
      } else {
        detail = `SPF exists but doesn't authorise us. Add \`include:${opts.spfInclude}\` (or \`mx\`) or your mail will be treated as spoofed.`;
      }
    }
    checks.push({
      key: "spf",
      label: "SPF — authorised senders",
      status,
      observed,
      expected: opts.spfExpected,
      host: domain,
      type: "TXT",
      detail,
    });
  }

  // ---- DKIM --------------------------------------------------------------
  {
    const published = (dkimTxt ?? []).find((t) => /(?:^|[;\s])p=/.test(t)) ?? "";
    const expected = opts.dkim?.txt ?? "";
    let status: CheckStatus = "fail";
    let detail: string;
    if (!expected) {
      status = "unknown";
      detail =
        "The mail server hasn't generated a DKIM key for this domain yet — there is nothing to publish. Reload in a moment.";
    } else if (!published) {
      detail = `No DKIM record at ${dkimHost}. Without it every message you send is unsigned, which is the single biggest reason mail lands in spam.`;
    } else if (dkimKey(published) && dkimKey(published) === dkimKey(expected)) {
      status = "pass";
      detail = `Published key matches the one the mail server signs with (selector \`${dkimSelector}\`).`;
    } else {
      detail =
        "A DKIM record exists but the public key does not match the mail server's current key — signatures will fail. Replace it with the value shown here.";
    }
    checks.push({
      key: "dkim",
      label: "DKIM — message signing",
      status,
      observed: truncate(published),
      expected: truncate(expected || "(no key on the mail server yet)"),
      host: dkimHost,
      type: "TXT",
      detail,
    });
  }

  // ---- DMARC -------------------------------------------------------------
  {
    const records = (dmarcTxt ?? []).filter((t) => /^v=DMARC1\b/i.test(t));
    const observed = records.join(" | ");
    let status: CheckStatus = "fail";
    let detail: string;
    if (records.length === 0) {
      detail =
        "No DMARC record. Some large providers now require one before they will trust bulk mail from a domain.";
    } else if (records.length > 1) {
      detail = "More than one DMARC record at _dmarc — receivers ignore all of them. Keep exactly one.";
    } else {
      const policy = records[0].match(/(?:^|;)\s*p\s*=\s*(none|quarantine|reject)/i)?.[1]?.toLowerCase();
      status = policy ? "pass" : "warn";
      detail = policy
        ? `Policy \`p=${policy}\` is published${policy === "none" ? " (monitor-only — tighten it once SPF and DKIM both pass)" : ""}.`
        : "A DMARC record exists but declares no `p=` policy, so receivers have nothing to enforce.";
    }
    checks.push({
      key: "dmarc",
      label: "DMARC — policy",
      status,
      observed,
      expected: opts.dmarcExpected,
      host: `_dmarc.${domain}`,
      type: "TXT",
      detail,
    });
  }

  return { domain, nameservers, checks, checkedAt };
}

