import { checkDeliverability, type DeliverabilityReport } from "./mail/deliverability";

// ---------- Deliverability self-check ----------

/**
 * Run the SPF / DKIM / DMARC / MX self-check for a subscription the caller owns.
 *
 * WHY: "my mail goes to spam" was previously undiagnosable from inside the
 * product — the platform owner hit exactly this and had to reach for an external
 * tool. This returns pass/fail per record with the value actually observed beside
 * the expected one, so the customer can see which DNS row is wrong.
 *
 * Two correctness rules this depends on:
 *   - DNS is read from the ZONE'S AUTHORITATIVE NAMESERVERS, never the system
 *     resolver (see lib/mail/deliverability.ts — this host's `hosts: files …`
 *     nsswitch order can answer from /etc/hosts and looks like a real lookup).
 *   - DKIM is compared against Mailcow's LIVE key, not `sub.dkimRecord`, which is
 *     a write-once cache that can outlive a key rotation.
 *
 * Rate-limited: each run makes several outbound DNS queries plus one Mailcow call.
 */
export async function checkEmailDeliverability(
  subscriptionId: string,
): Promise<{ error?: string; report?: DeliverabilityReport }> {
  const user = await requireUser();

  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
  if (!sub) return { error: "Subscription not found." };
  if (sub.userId !== user.id) return { error: "Not your subscription." };

  const rl = checkRateLimit(`email-deliverability:${user.id}`, { max: 10, windowMs: 60_000 });
  if (!rl.ok) return { error: `Too many checks. Try again in ${rl.retryAfterSec}s.` };

  // LIVE key only. A failure here degrades the DKIM row to "unknown" rather than
  // silently comparing against a cached value that may no longer sign anything.
  let dkim: { selector: string; txt: string } | null = null;
  if (mailcowConfigured()) {
    try {
      const live = await mcGetDkimDetails(sub.domainName);
      if (live) dkim = { selector: live.selector, txt: live.txt };
    } catch (e) {
      console.warn(`[mailcow] live dkim lookup for ${sub.domainName} failed:`, e);
    }
  }

  try {
    const report = await checkDeliverability({
      domain: sub.domainName,
      mailHost: MAIL_HOST,
      spfInclude: SPF_INCLUDE,
      spfExpected: SPF_VALUE,
      dmarcExpected: DMARC_VALUE,
      dkim,
    });
    return { report };
  } catch (e) {
    console.warn(`[deliverability] check for ${sub.domainName} failed:`, e);
    return { error: "Couldn't complete the DNS check right now. Please try again in a moment." };
  }
}

// Local-part of an email address: RFC-ish, conservative. No leading/trailing dot.
const localPartRe = /^[a-z0-9]+(?:[._-][a-z0-9]+)*$/;

